                rounded = 0.0
            aggregate.append(rounded)

    return {
        "round_id": round_id,
        "participant_count": participant_count,
        "total_sample_count": total_sample_count,
        "dimension": dimension,
        "aggregate": aggregate,
        "clipped_participants": sorted(clipped),
    }

